    async _initStreams() {
        let streams = [];
        // 主号
        let mainToken = this.loadData('account_token_0');
        if (mainToken) {
            streams.push({
                name: '主号',
                token: mainToken,
                eliminated: 0,
                total: -1,
            });
        }
        // 附属号
        let subAccounts = JSON.parse(this.loadSetting('sub_accounts') || '[]');
        for (let i = 0; i < subAccounts.length; i++) {
            let t = this.loadData(`account_token_${i + 1}`);
            if (!t) continue;
            streams.push({
                name: subAccounts[i].name,
                token: t,
                eliminated: 0,
                total: -1,
            });
        }
        let pageCache = {};
        let seen = new Set();
        for (let s of streams) {
            try {
                let result = await this._fetchFavoritesPage(s.token, 0, '-datetime_updated', s.name);
                s.total = result.total;
                if (!pageCache[s.token]) pageCache[s.token] = {};
                pageCache[s.token][1] = result.list;
            } catch (e) {
                UI.showMessage(`${s.name}: ${e}`);
                s.total = 0;
            }
            await new Promise(r => setTimeout(r, 500));
        }
        this._mergeState = { streams, pageCache, seen };
    }

    /**
     * 获取某账号第 pageNo 页（1-based），自动缓存
     */
    async _getPage(token, pageNo) {
        let pc = this._mergeState.pageCache;
        if (!pc[token]) pc[token] = {};
        let cached = pc[token][pageNo];
        if (cached) return cached;
        let result = await this._fetchFavoritesPage(token, (pageNo - 1) * 30, '-datetime_updated', '');
        pc[token][pageNo] = result.list;
        return result.list;
    }

    /**
     * 一种针对分页访问代价高昂的多个降序流，以比例分配跳跃步长、分治排除的方式快速定位全局第 k 大元素的多路选择算法。
     * @param {Array} streams - [{ eliminated, total, token }]
     * @param {number} k - 1-based 全局目标排名
     * @returns {Object|null} 第 K 大元素，超出范围返回 null
     */
    async _proportionalFindKth(streams, k) {
        const PAGE_SIZE = 30;

        while (true) {
            let active = streams.filter(s => s.total > 0 && s.eliminated < s.total);
            if (active.length === 0) return null;

            let M = active.length;

            if (k === 1 || k - 1 < M) {
                let best = null;
                let bestDate = '';
                for (let s of active) {
                    let idx = s.eliminated;
                    let page = await this._getPage(s.token, Math.floor(idx / PAGE_SIZE) + 1);
                    let item = page[idx % PAGE_SIZE];
                    let dt = item.comic.datetime_updated || '';
                    if (!best || dt > bestDate) { best = { stream: s, item }; bestDate = dt; }
                }
                best.stream.eliminated++;
                if (k === 1) return best.item;
                k--;
                continue;
            }

            let totalRemaining = active.reduce((sum, s) => sum + s.total - s.eliminated, 0);
            let E = k - 1 - M;

            for (let s of active) {
                let remaining = s.total - s.eliminated;
                let bonus = Math.floor(E * remaining / totalRemaining);
                s._step = Math.min(remaining, 1 + bonus);
                s._probeIdx = s.eliminated + s._step - 1;
            }

            for (let s of active) {
                let pageNo = Math.floor(s._probeIdx / PAGE_SIZE) + 1;
                let wasCached = this._mergeState.pageCache[s.token] && this._mergeState.pageCache[s.token][pageNo];
                await this._getPage(s.token, pageNo);
                if (!wasCached) {
                    await new Promise(r => setTimeout(r, 500));
                }
            }

            let bestStream = null;
            let bestDate = '';
            for (let s of active) {
                let pageNo = Math.floor(s._probeIdx / PAGE_SIZE) + 1;
                let item = this._mergeState.pageCache[s.token][pageNo][s._probeIdx % PAGE_SIZE];
                let dt = item.comic.datetime_updated || '';
                if (!bestStream || dt > bestDate) { bestStream = s; bestDate = dt; }
            }

            bestStream.eliminated += bestStream._step;
            k -= bestStream._step;
        }
    }

    async _loadAllFavorites(page) {
        if (page === 1) {
            this._clearMergeState();
        }
        if (!this._mergeState) {
            await this._initStreams();
        }

        for (let s of this._mergeState.streams) {
            s.eliminated = 0;
        }

        let skipCount = (page - 1) * 30 ;
        if (skipCount > 0) {
            await this._proportionalFindKth(this._mergeState.streams, skipCount);
        }

        let uniqueItems = [];
        for (let i = 0; i < 30; i++) {
            let item = await this._proportionalFindKth(this._mergeState.streams, 1);
            if (!item) break;
            if (!this._mergeState.seen.has(item.comic.uuid)) {
                this._mergeState.seen.add(item.comic.uuid);
                uniqueItems.push(item);
            }
        }

        function parseComic(item) {
            let comic = item.comic;
            let tags = [];
            if (comic.theme) {
                tags = comic.theme.map(t => t.name);
            }
            let author = null;
            if (Array.isArray(comic.author) && comic.author.length > 0) {
                author = comic.author[0].name;
            }
            return {
                id: comic.path_word,
                title: comic.name,
                subTitle: author,
                cover: comic.cover,
                tags: tags,
                description: comic.datetime_updated
            };
        }

        let sumTotal = this._mergeState.streams.reduce((s, st) => s + Math.max(0, st.total), 0);
        let maxPage = Math.max(1, Math.ceil(sumTotal / 30));

        return {
            comics: uniqueItems.map(parseComic),
            maxPage: maxPage
        };
    }

    comic = {
        loadInfo: async (id) => {
            let getChapters = async (id, groups) => {
                let fetchSingle = async (id, path) => {
                    let reqId = await this.getReqID();
                    let res = await Network.get(
                        `${this.apiUrl}/api/v3/comic/${id}/group/${path}/chapters?limit=100&offset=0&in_mainland=true&request_id=${reqId}`,
                        this.headers
                    );
                    if (res.status !== 200) {
                        throw `Invalid status code: ${res.status}`;
                    }
                    let data = JSON.parse(res.body);
                    let eps = new Map();
                    data.results.list.forEach((e) => {
                        let title = e.name;
                        let id = e.uuid;
                        eps.set(id, title);
                    });
                    let maxChapter = data.results.total;
                    if (maxChapter > 100) {
                        let offset = 100;
                        while (offset < maxChapter) {
                            res = await Network.get(
                                `${this.apiUrl}/api/v3/comic/${id}/group/${path}/chapters?limit=100&offset=${offset}`,
                                this.headers
                            );
                            if (res.status !== 200) {
                                throw `Invalid status code: ${res.status}`;
                            }
                            data = JSON.parse(res.body);
                            data.results.list.forEach((e) => {
                                let title = e.name;
                                let id = e.uuid;
                                eps.set(id, title)
                            });
                            offset += 100;
                        }
                    }
                    return eps;
                };
                let keys = Object.keys(groups);
                let result = {};
                let futures = [];
                for (let group of keys) {
                    let path = groups[group]["path_word"];
                    futures.push((async () => {
                        result[group] = await fetchSingle(id, path);
                    })());
                }
                await Promise.all(futures);
                if (this.isAppVersionAfter("1.3.0")) {
                    // 支持多分组
                    let sortedResult = new Map();
                    for (let key of keys) {
                        let name = groups[key]["name"];
                        sortedResult.set(name, result[key]);
                    }
                    return sortedResult;
                } else {
                    // 合并所有分组
                    let merged = new Map();
                    for (let key of keys) {
                        for (let [k, v] of result[key]) {
                            merged.set(k, v);
                        }
                    }
                    return merged;
                }
            }

            let getFavoriteStatus = async (id) => {
                let favAccounts = await this._checkFavoriteAccounts(id);
                return favAccounts.length > 0;
            }
            let reqId = await this.getReqID();
            let results = await Promise.all([
                Network.get(
                    `${this.apiUrl}/api/v3/comic2/${id}?in_mainland=true&request_id=${reqId}&platform=3`,
                    this.headers
                ),
                getFavoriteStatus.bind(this)(id)
            ])

            if (results[0].status !== 200) {
                throw `Invalid status code: ${res.status}`;
            }

            let data = JSON.parse(results[0].body).results;
            let comicData = data.comic;

            let title = comicData.name;
            let cover = comicData.cover;
            let authors = comicData.author.map(e => e.name);
            // author_path_word_dict长度限制为最大100
            if (Object.keys(this.author_path_word_dict).length > 100) {
                this.author_path_word_dict = {};
            }
            // 储存author对应的path_word
            comicData.author.forEach(e => (this.author_path_word_dict[e.name] = e.path_word));
            let tags = comicData.theme.map(e => e?.name).filter(name => name !== undefined && name !== null);
            let updateTime = comicData.datetime_updated ? comicData.datetime_updated : "";
            let description = comicData.brief;
            let chapters = await getChapters(id, data.groups);
            let status = comicData.status.display;

            return {
                title: title,
                cover: cover,
                description: description,
                tags: {
                    "作者": authors,
                    "更新": [updateTime],
                    "标签": tags,
                    "状态": [status],
                },
                chapters: chapters,
                isFavorite: results[1],
                subId: comicData.uuid
            }
        },
        loadEp: async (comicId, epId) => {
            let attempt = 0;
            const maxAttempts = 5;
            let res;
            let data;

            while (attempt < maxAttempts) {
                try {
                    let reqId = await this.getReqID();
                    res = await Network.get(
                        `${this.apiUrl}/api/v3/comic/${comicId}/chapter2/${epId}?in_mainland=true&request_id=${reqId}`,
                        {
                            ...this.headers
                        }
                    );

                    if (res.status === 210) {
                        // 210 indicates too frequent access, extract wait time
                        let waitTime = 40000; // Default wait time 40s
                        try {
                            let responseBody = JSON.parse(res.body);
                            if (
                                responseBody.message &&
                                responseBody.message.includes("Expected available in")
                            ) {
                                let match = responseBody.message.match(/(\d+)\s*seconds/);
                                if (match && match[1]) {
                                    waitTime = parseInt(match[1]) * 1000;
                                }
                            }
                        } catch (e) {
                            console.log(
                                "Unable to parse wait time, using default wait time 40s"
                            );
                        }
                        console.log(`Chapter${epId} access too frequent, waiting ${waitTime / 1000}s`);
                        await new Promise((resolve) => setTimeout(resolve, waitTime));
                        throw "Retry";
                    }

                    if (res.status !== 200) {
                        throw `Invalid status code: ${res.status}`;
                    }

                    data = JSON.parse(res.body);
                    // console.log(data.results.chapter);
                    // Handle image link sorting
                    let imagesUrls = data.results.chapter.contents.map((e) => e.url);
                    let orders = data.results.chapter.words;

                    // Replace origin images urls to selected quality images urls
                    let hdImagesUrls = imagesUrls.map((url) =>
                        url.replace(/([./])c\d+x\.[a-zA-Z]+$/, `$1c${this.imageQuality}x.webp`)
                    )

                    let images = new Array(hdImagesUrls.length).fill(""); // Initialize an array with the same length as imagesUrls

                    // Arrange images according to orders
                    for (let i = 0; i < hdImagesUrls.length; i++) {
                        images[orders[i]] = hdImagesUrls[i];
                    }

                    return {
                        images: images,
                    };
                } catch (error) {
                    if (error !== "Retry") {
                        throw error;
                    }
                    attempt++;
                    if (attempt >= maxAttempts) {
                        throw error;
                    }
                }
            }
        },
        loadComments: async (comicId, subId, page, replyTo) => {
            let url = `${this.apiUrl}/api/v3/comments?comic_id=${subId}&limit=20&offset=${(page - 1) * 20}`;
