          referer: refererUrl,
        },
      };
    },
    /**
     * [Optional] provide configs for a thumbnail loading
     * @param url {string}
     * @returns {ImageLoadingConfig | Promise<ImageLoadingConfig>}
     *
     * `ImageLoadingConfig.modifyImage` and `ImageLoadingConfig.onLoadFailed` will be ignored.
     * They are not supported for thumbnails.
     */
    onThumbnailLoad: (url) => {
      return {
        url,
        headers: {
          referer: refererUrl,
        },
      };
    },
    onClickTag: (namespace, tag) => {
      let fixedNamespace = undefined;
      switch (namespace) {
        case "type":
          fixedNamespace = "type";
          break;
        case "groups":
          fixedNamespace = "group";
          break;
        case "artists":
          fixedNamespace = "artist";
          break;
        case "language":
          fixedNamespace = "language";
          break;
        case "series":
          fixedNamespace = "series";
          break;
        case "characters":
          fixedNamespace = "character";
          break;
        case "females":
          fixedNamespace = "female";
          break;
        case "males":
          fixedNamespace = "male";
          break;
        case "others":
          fixedNamespace = "tag";
          break;
        default:
          break;
      }
      if (!fixedNamespace) {
        throw new Error("不支持的标签命名空间: " + namespace);
      }
      const keyword = fixedNamespace + ":" + tag.replaceAll(" ", "_");
      return {
        page: "search",
        attributes: {
          keyword,
        },
      };
    },
    /**
     * [Optional] Handle links
     */
    link: {
      /**
       * set accepted domains
       */
      domains: ["hitomi.la"],
      /**
       * parse url to comic id
       * @param url {string}
       * @returns {string | null}
       */
      linkToId: (url) => {
        const reg = /https:\/\/hitomi\.la\/\w+\/[^\/]+-(\d+)\.html/;
        const r = reg.exec(url);
        if (r) {
          return r[1];
        } else {
          throw new Error("Invalid gallery url of hitomi.la");
        }
      },
    },
    // enable tags translate
    enableTagsTranslate: true,
  };
}

