                "referer": epId,
              },
              `id=${encodeURIComponent(readConfig.apiCid || readConfig.cid)}&aid=${encodeURIComponent(readConfig.aid)}`
            );
            const apiImages = parseReadApiImages(readRes, epId);
            readApiDebug += `; status=${readRes.status || "?"}; apiImages=${apiImages.length}; preview=${String(readRes.body || "").slice(0, 120)}`;
            apiImages.forEach((url) =>
              addImageUrl(images, url, epId)
            );
            images = filterReaderImages(images, res.body);
            if (!looksLikeReaderSet(images, "fallback")) {
              if (lockedPlaceholderCount >= 3) {
                throw new Error(
                  `该章节页面没有下发正文图片，只返回了 ${lockedPlaceholderCount} 张未解锁/VIP 占位图（/static/msnot_vip.png）。这不是图片地址规则问题，脚本不能凭空获取未下发的正文图。`
                );
              }
              const canonicalChapterName = canBuildImagesFromReadConfig(readConfig)
                ? await fetchCanonicalChapterName(readConfig, epId)
                : "";
              const generatorConfig = canonicalChapterName
                ? { ...readConfig, chaptername: canonicalChapterName }
                : readConfig;
              const generatedImages = buildImagesFromReadConfig(generatorConfig);
              readApiDebug += `; canonical=${canonicalChapterName || "-"}; generated=${generatedImages.length}`;
              generatedImages.forEach((url) =>
                addImageUrl(images, url, epId)
              );
              images = filterReaderImages(images, res.body);
            }
          } else {
            readApiDebug = `read api skipped; comicId=${String(comicId || "").slice(0, 80)}; epId=${String(epId || "").slice(0, 80)}; html=${String(res.body || "").slice(0, 120)}`;
          }
        }

        if (
          strictImages.length === 0 &&
          !looksLikeReaderSet(images, "fallback")
        ) {
          throw new Error(`没有找到可靠的正文漫画图片；候选 ${images.length} 张；${readApiDebug}`);
        }

        if (
          strictImages.length === 0 &&
          !looksLikeReaderSet(images, "fallback")
        ) {
          throw new Error(`页面中没有找到可靠的正文漫画图片；已排除封面、推荐图、占位图和少量杂图（候选 ${images.length} 张）`);
        }
        return {
          images,
        };
      } catch (err) {
        throw new Error(`加载章节失败：${err.message}`);
      }
    },
    onImageLoad: (url, comicId, epId) => {
      return buildImageLoadConfig(parseCandidateImageUrl(url), 0, comicId, epId);
    },
  };
}

/** @type {import('./_venera_.js')} */

const JCOMIC_BASE = "https://jcomic.net";
const JCOMIC_REFERER = JCOMIC_BASE + "/";

function trimTitle(raw) {
  if (!raw) return "";
  const idx = raw.lastIndexOf(" (");
  if (idx > 0) return raw.slice(0, idx).trim();
  return raw.trim();
}

function parseIdFromHref(href) {
  if (!href) return null;
  try {
    const u = href.split("?")[0];
    const parts = u.split("/").filter(Boolean); // 过滤空字符串
    if (parts.length >= 2) {
      return decodeURIComponent(parts[1]);
    }
    return decodeURIComponent(parts[parts.length - 1]);
  } catch {
    return null;
  }
}

function parseEpIdFromHref(href) {
  if (!href) return null;
  const u = href.split("?")[0];
  const parts = u.split("/").filter(Boolean);
  if (parts.length >= 3) {
    return decodeURIComponent(parts[2]);
  }
  return null;
}

/**
 * 解析作品卡片 -> Comic
 * @param {Element} card
 */
function parseComicCard(card) {
  try {
    const link = card.querySelector('a[href^="/eps/"], a[href^="/page/"]');
    if (!link) return null;
    const href = link.attributes["href"];
    const id = parseIdFromHref(href);
    if (!id) return null;

    const img = card.querySelector("img.comic-thumb");
    const cover = img ? img.attributes["src"] : "";

    const titleEl = card.querySelector("p.comic-title");
    const rawTitle = titleEl ? titleEl.text.trim() : id;
    const title = trimTitle(rawTitle);

    // 作者
    const authorButtons = card.querySelectorAll('a[href^="/author/"] button');
    const authors = Array.from(authorButtons).map((b) => b.text.trim());
    const subTitle = authors.join(" ");

    // 分类标签
    const catButtons = card.querySelectorAll('a[href^="/cat/"] button');
    let tags = [];
    if (catButtons.length) {
        tags = Array.from(catButtons).map((b) => b.text.trim());
    } else {
    // 有些结构是 a[href^="/cat/..."] 包着文字
    const catAnchors = card.querySelectorAll('a[href^="/cat/"]');
    tags = Array.from(catAnchors)
    .map((a) => a.text.trim())
    .filter(Boolean);
}   

    // 最后更新
    const dateEl = card.querySelector("p.comic-date");
    const description = dateEl ? dateEl.text.trim() : "";

    return new Comic({
      id,
      title,
      subTitle,
      cover,
      tags,
      language: "zh-Hant",
      description,
    });
  } catch (e) {
    return null;
  }
}

/**
 * 通用：解析分页最大页数
 * @param {HtmlDocument} doc
 */
function parseMaxPage(doc) {
  const pag = doc.querySelector("ul.pagination");
  if (!pag) return 1;
  const as = pag.querySelectorAll("a");
  let max = 1;
  as.forEach((a) => {
    const t = a.text.trim();
    const n = parseInt(t, 10);
    if (!Number.isNaN(n) && n > max) max = n;
  });
  return max;
}

/**
 * 通用：解析列表页所有作品
 * @param {HtmlDocument} doc
 */
function parseComicList(doc) {
  const cards = doc.querySelectorAll(
    'div.row.col-lg-4.col-md-6.col-xs-12, div.row.col-md-6.col-xs-12'
  );
  const result = [];
  cards.forEach((card) => {
    const c = parseComicCard(card);
    if (c) result.push(c);
  });
  return result;
}

