                        param: `genre:${genreId}`
                    }
                }
            }
            if (namespace === '作者') {
                const authors = this.loadData('kavita_authors')
                const authorId = authors.find(item => item.name === tag)?.id
                if (authorId) {
                    return {
                        action: 'category',
