                                    // try to match category id or name
                                    for (const [fid, fname] of Object.entries(folders)) {
                                        if (String(v) === fid || String(v) === fname) {
                                            if (!favorited.includes(fid)) favorited.push(fid)
                                        }
                                    }
                                }
                            }
                        }
                    }
