                        });
                } else {
                        data.push(latest.comics);
                }

                return {
                    data,
                    maxPage: latest.maxPage
                };
            }
        }
    ]

    // categories
    category = {
        /// title of the category page, used to identify the page, it should be unique
        title: "nhentai",
        parts: [
            {
                name: "Language",

                type: "fixed",

                categories: ["Chinese", "English", "Japanese"],

